{
  "name": "@amykit/plugin-concurrent-engine",
  "version": "0.6.0",
  "description": "Advances one work item per tick, moving every lane of a fork at once.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/concurrent-engine"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "amy": {
    "about": "Use it in place of serial-engine when a workflow forks into lanes that should move together, such as ticket-to-qa running its gate and its self-review side by side. Everything else is the serial engine's, settings included: the same claim on a queue item and the same budget check before each lane's call. An install mounts one engine, so pick this one or serial-engine, with file-queue and file-store beside it."
  },
  "dependencies": {
    "@amykit/core": "^0.6.0",
    "@amykit/plugin-serial-engine": "^0.6.0"
  },
  "devDependencies": {
    "@amykit/plugin-file-queue": "^0.6.0",
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import { Engine, definePlugin, deferred } from "@amykit/core";
import { configSchema, engineFor } from "@amykit/plugin-serial-engine";

/**
 * The serial engine with the lanes of a fork moved side by side.
 *
 * Everything else is the serial engine's, on purpose: the atomic claim of one
 * queue item, one move per look in every lane, and the budget asked before
 * each lane's call. A record waiting in a fork is claimed once, every lane
 * with a move makes it, and the moves are folded into that one record. See
 * `docs/design/a-workflow-runs-on-lanes.md`.
 */
export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-concurrent-engine",
  configSchema,
  register(registry, ctx) {
    registry.engine(deferred((): Engine => engineFor(ctx, "concurrent")));
  },
});
